CREATE TABLE IF NOT EXISTS linestop_db (
  id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
  line_key VARCHAR(32) NOT NULL,
  machine_name VARCHAR(191) NOT NULL,
  normalized_name VARCHAR(191) NOT NULL,
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY linestop_db_line_machine_unique (line_key, machine_name),
  KEY linestop_db_active_lookup (line_key, is_active)
);

